while key < 2048 { state = push(state, [0]) key += 1 }
export func snapshot() { return state }
func observe(n) { assert_equal(state[0][0], n) assert_equal(state[2][0], n) }
export func edit(n) { state[0] = [n / 0]
state[0] = [n]
state[1] = [n]
state[2] = [n]
return n }

from owner import edit, snapshot
let original := snapshot()
mut count := 1 mut caught := 0
while count <= 2 { try { edit(count) } except err { caught += 1 }
count += 1 }
assert_equal(caught, 2)
let result := snapshot()
assert_equal(result[0][0], 0)
assert_equal(result[1][0], 0)
assert_equal(result[2][0], 0)
assert_equal(original[0][0], 0)
print("BATCH BOUNDARY PASS")

