    #[test]
    fn host_removal_after_capture_retains_local_membership() {
        for width in [0, 128, 8192] {
            let mut env = Environment::new();
            env.define("fixed".into(), Value::Int(11));
            env.push_scope();
            env.define_with_kind("fixed".into(), Value::Int(7), BindingKind::Const);
