/// Open, bounded, atomically published private-file spool state.
///
/// The live file is reachable only through a `Value::PrivateSpool` handle. If
/// the handle is dropped or explicitly aborted before publication, the
/// same-directory temporary file is removed.
pub struct PrivateSpoolState {
    pub file: Option<File>,
    pub destination: PathBuf,
    pub temp: PathBuf,
    pub mode: u32,
    pub max_bytes: u64,
    pub bytes_written: u64,
    pub hasher: sha2::Sha256,
}

impl Drop for PrivateSpoolState {
    fn drop(&mut self) {
        self.file.take();
        let _ = std::fs::remove_file(&self.temp);
    }
}

// Forward declaration - Environment is in a sibling module
use super::environment::Environment;

/// Hash map for integer-keyed dictionaries.
pub type IntDictMap = HashMap<i64, Value, BuildHasherDefault<NoHashHasher<i64>>>;

/// Dense vector for integer-keyed dictionaries with non-negative keys.
pub type DenseIntDict = Vec<Value>;

/// Dense vector for integer-keyed dictionaries with optional int values.
pub type DenseIntDictInt = Vec<Option<i64>>;

/// Dense vector for integer-keyed dictionaries with int values only.
pub type DenseIntDictIntFull = Vec<i64>;

/// Hash map for string-keyed dictionaries.
pub type DictMap = HashMap<Arc<str>, Value, BuildHasherDefault<AHasher>>;

/// One-shot parts of an incremental HTTP response.
///
/// The response body is consumed by the routed HTTP server while stream events
/// are dispatched to the Kujo callback on the interpreter/VM thread. Keeping
/// this state behind an `Option` makes a streaming response explicitly
/// single-use even though runtime values are cheaply cloneable.
pub struct HttpResponseStreamParts {
    pub body: Box<dyn std::io::Read + Send>,
    pub events: Receiver<Value>,
    pub cancelled: Arc<std::sync::atomic::AtomicBool>,
    pub content_length: Option<usize>,
}

pub type SharedHttpResponseStream = Arc<Mutex<Option<HttpResponseStreamParts>>>;

/// A routed HTTP upload that authorizes from request metadata before any body
/// bytes are accepted, then streams the body into a bounded private file.
#[derive(Clone)]
pub struct HttpUploadRoute {
    pub method: String,
    pub path: String,
    pub spool_directory: String,
    pub max_body_bytes: u64,
    pub authorize: Value,
    pub handler: Value,
}

/// Stores function bodies and drops deeply nested statement trees iteratively.
///
/// Function bodies can contain very deep nesting through statements like loops,
/// `if`, `match`, and nested function definitions. Rust's default drop is recursive
/// for this shape and can overflow the stack at shutdown or when large AST graphs
/// are released.
///
/// This container keeps existing call sites stable while replacing the old
/// leak-on-drop strategy with a non-recursive drop traversal.
pub struct LeakyFunctionBody {
    id: usize,
    pub(crate) lexical_name: Option<String>,
}

#[derive(Clone)]
struct FunctionBodyStorage {
    body: Vec<Stmt>,
    capture_independence: OnceLock<Option<super::capture_independence::Proof>>,
}

struct StoredFunctionBody {
    refs: usize,
    storage: Arc<FunctionBodyStorage>,
}

static FUNCTION_BODY_STORE: OnceLock<Mutex<HashMap<usize, StoredFunctionBody>>> = OnceLock::new();
static NEXT_FUNCTION_BODY_ID: AtomicUsize = AtomicUsize::new(1);

fn function_body_store() -> &'static Mutex<HashMap<usize, StoredFunctionBody>> {
    FUNCTION_BODY_STORE.get_or_init(|| Mutex::new(HashMap::new()))
}

impl Drop for FunctionBodyStorage {
    fn drop(&mut self) {
        let body = std::mem::take(&mut self.body);
        drop_stmt_tree_iterative(body);
    }
}

fn drop_stmt_tree_iterative(root: Vec<Stmt>) {
    let mut stack = root;

    while let Some(mut stmt) = stack.pop() {
        match &mut stmt {
            Stmt::FuncDef { body, .. }
            | Stmt::Loop { body, .. }
            | Stmt::For { body, .. }
            | Stmt::While { body, .. }
            | Stmt::Block(body)
            | Stmt::Spawn { body }
            | Stmt::Test { body, .. }
            | Stmt::TestSetup { body }
            | Stmt::TestTeardown { body } => {
                stack.extend(std::mem::take(body));
            }
            Stmt::Match { cases, default, .. } => {
                for (_, case_body) in std::mem::take(cases) {
                    stack.extend(case_body);
                }
                if let Some(default_body) = default.take() {
                    stack.extend(default_body);
                }
            }
            Stmt::If { then_branch, else_branch, .. } => {
                stack.extend(std::mem::take(then_branch));
                if let Some(else_body) = else_branch.take() {
                    stack.extend(else_body);
                }
            }
            Stmt::TryExcept { try_block, except_block, .. } => {
                stack.extend(std::mem::take(try_block));
                stack.extend(std::mem::take(except_block));
            }
            Stmt::Export { stmt } => {
                let inner_stmt = std::mem::replace(stmt, Box::new(Stmt::Block(Vec::new())));
                stack.push(*inner_stmt);
            }
            Stmt::StructDef { methods, .. } | Stmt::TestGroup { tests: methods, .. } => {
                stack.extend(std::mem::take(methods));
            }
            Stmt::Let { .. }
            | Stmt::Const { .. }
            | Stmt::Assign { .. }
            | Stmt::EnumDef { .. }
            | Stmt::ExprStmt(_)
            | Stmt::Return(_)
            | Stmt::Break
            | Stmt::Continue
            | Stmt::Import { .. } => {}
        }
    }
}

pub struct FunctionBodyRef {
    storage: Arc<FunctionBodyStorage>,
}

pub(super) fn is_capture_primitive(value: &Value) -> bool {
    matches!(
        value,
        Value::Int(_)
            | Value::Float(_)
            | Value::Bool(_)
            | Value::Str(_)
            | Value::Bytes(_)
            | Value::Null
    )
}

impl FunctionBodyRef {
    /// Boxed array payloads are profitable only when no later statement can
    /// force publication. This allocation-free shape check is independent of
    /// capture purity: RHS/index callbacks still disable admission normally.
    pub(super) fn can_defer_boxed_array(&self) -> bool {
        use crate::ast::Expr;
        let (assignment, result) = match self.storage.body.as_slice() {
            [assignment] => (assignment, None),
            [assignment, Stmt::Return(result)] => (assignment, result.as_ref()),
            _ => return false,
        };
        let Stmt::Assign { target: Expr::IndexAccess { object, .. }, .. } = assignment else {
            return false;
        };
        let Expr::Identifier(root) = object.as_ref() else { return false };
        match result {
            None => true,
            Some(Expr::Identifier(name)) => name != root,
            Some(Expr::Int(_) | Expr::Float(_) | Expr::String(_) | Expr::Bool(_) | Expr::None) => {
                true
            }
            _ => false,
        }
    }

    pub(super) fn can_batch_nested_dictionary_writes(
        &self,
        params: &[String],
        args: &[Value],
        env: &super::environment::Environment,
    ) -> super::nested_spill_proof::SpillPolicy {
        let Some(proof) = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
        else {
            return super::nested_spill_proof::SpillPolicy::default();
        };
        if proof.nested_spill_region() {
            let dictionary =
                super::nested_spill_proof::eligible(&self.storage.body, params, args, env);
            if dictionary.capacity != 0 {
                dictionary
            } else {
                super::row_spill_proof::eligible_policy(&self.storage.body, params, args, env)
            }
        } else {
            super::nested_spill_proof::SpillPolicy::default()
        }
    }

    pub(super) fn can_batch_dictionary_writes(
        &self,
        params: &[String],
        args: &[Value],
        env: &super::environment::Environment,
    ) -> bool {
        let Some(proof) = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
        else {
            return false;
        };
        !proof.read_only
            && proof.sparse_write_region()
            && args.iter().all(is_capture_primitive)
            && proof.required_parameters.iter().enumerate().all(|(index, name)| {
                proof.whole_value_mask & (1u32 << index) == 0
                    || params.contains(name)
                    // Inspect the entered capture on every invocation. A captured
                    // primitive can become an operator-bearing value between calls.
                    // Borrowing also avoids materializing pending/live snapshots.
                    || env.nested_spill_proof_value(name).is_some_and(is_capture_primitive)
            })
    }

    pub(super) fn dictionary_insertion_bound(&self, params: &[String], args: &[Value]) -> u16 {
        let Some(Some(proof)) = self.storage.capture_independence.get() else { return 0 };
        match proof.insertion_bound {
            u8::MAX => {
                super::dictionary_insertion_proof::runtime_bound(&self.storage.body, params, args)
            }
            n => u16::from(n),
        }
    }

    pub(super) fn read_capture_proof(
        &self,
        args: &[Value],
    ) -> Option<&super::capture_independence::Proof> {
        let proof = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
            .as_ref()?;
        if !proof.read_only || (proof.primitive_arguments && !args.iter().all(is_capture_primitive))
        {
            return None;
        }
        Some(proof)
    }

    /// Cache syntax analysis with the immutable body, not an environment or
    /// callable's publicly constructible parameter list. Recheck actual parameter
    /// names and dynamic operand kinds on every invocation.
    pub(crate) fn can_skip_capture_setup(&self, params: &[String], args: &[Value]) -> bool {
        let Some(proof) = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
        else {
            return false;
        };
        proof.required_parameters.iter().all(|name| params.contains(name))
            && (!proof.primitive_arguments
                || args.iter().all(|value| {
                    matches!(
                        value,
                        Value::Int(_)
                            | Value::Float(_)
                            | Value::Bool(_)
                            | Value::Str(_)
                            | Value::Bytes(_)
                            | Value::Null
                    )
                }))
    }
}

impl Deref for FunctionBodyRef {
    type Target = Vec<Stmt>;

    fn deref(&self) -> &Self::Target {
        &self.storage.body
    }
}

impl Clone for LeakyFunctionBody {
    fn clone(&self) -> Self {
        let mut store = function_body_store().lock().unwrap();
        if let Some(entry) = store.get_mut(&self.id) {
            entry.refs += 1;
        }

        LeakyFunctionBody { id: self.id, lexical_name: self.lexical_name.clone() }
    }
}

impl Drop for LeakyFunctionBody {
    fn drop(&mut self) {
        let mut store = function_body_store().lock().unwrap();
        if let Some(entry) = store.get_mut(&self.id) {
            if entry.refs > 1 {
                entry.refs -= 1;
            } else {
                store.remove(&self.id);
            }
        }
    }
}

impl LeakyFunctionBody {
    pub fn new(body: Vec<Stmt>) -> Self {
        let id = NEXT_FUNCTION_BODY_ID.fetch_add(1, Ordering::Relaxed);
        let storage = Arc::new(FunctionBodyStorage { body, capture_independence: OnceLock::new() });

        let mut store = function_body_store().lock().unwrap();
        store.insert(id, StoredFunctionBody { refs: 1, storage });

        LeakyFunctionBody { id, lexical_name: None }
    }

    pub(crate) fn named(name: &str, body: Vec<Stmt>) -> Self {
        let mut function = Self::new(body);
        function.lexical_name = Some(name.to_owned());
        function
    }

    pub fn get(&self) -> FunctionBodyRef {
        let store = function_body_store().lock().unwrap();
        if let Some(entry) = store.get(&self.id) {
            FunctionBodyRef { storage: Arc::clone(&entry.storage) }
        } else {
            FunctionBodyRef {
                storage: Arc::new(FunctionBodyStorage {
                    body: Vec::new(),
                    capture_independence: OnceLock::new(),
                }),
            }
        }
    }

    pub(crate) fn same_identity(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

#[cfg(test)]
mod tests {
    #[cfg(feature = "runtime-db")]
