        config.insert("min_connections".into(), Value::Int(0));
        config.insert("max_connections".into(), Value::Int(1));
        let pool =
            ConnectionPool::new("sqlite".into(), path.to_string_lossy().into(), config).unwrap();
        for _ in 0..2 {
