assert_equal(mixed(20),20)
assert_equal(snapshot()[0],20) assert_equal(snapshot()[1],[20]) assert_equal(snapshot()[2],{"v":20})
assert_equal(aliases(30),30)
assert_equal(snapshot()[0],{"v":30}) assert_equal(snapshot()[7],[31])
