assert_equal(callback(50),50) assert_equal(snapshot()[0],[50]) assert_equal(snapshot()[1],[50])
assert_equal(rewrite(60),60) assert_equal(snapshot()[0],[159]) assert_equal(snapshot()[7],[67])
