"###,
        ),
        (
            "deep",
            r###"mut root := {"outer": [{"row": [0,0,0,0,0,0,0,0]}]}
export func snapshot() { return root["outer"][0]["row"] }
export func batch(n) { mut j := 0 while j < 8 { root["outer"][0]["row"][j] = [n+j] j += 1 } return n }
