export func callback(n) { root["outer"][0]["row"][0] = [n] root["outer"][0]["row"][1] = observe() root["outer"][0]["row"][2] = [n] return n }
export func rewrite(n) { mut j := 0 while j < 8 { root["outer"][0]["row"][j] = [n+j] j += 1 } root["outer"][0]["row"][-8] = [n+99] return n }
