// Diagnostic only: process-wide requested allocation traffic, not retained heap.
// Setup/parse are excluded; task workers and callback execution are included.
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicU64, Ordering::Relaxed};
use std::sync::{Arc, Mutex};
use std::time::Duration;
use kujo::{compiler::Compiler, lexer, parser::Parser, vm::VM};
// Counts every successful Rust global allocation, including setup, so frees of
// setup objects cannot underflow a measurement window. Native malloc/mmap and
// allocator arena overhead are deliberately outside these requested-live bytes.
static LIVE: AtomicU64 = AtomicU64::new(0);
static PEAK: AtomicU64 = AtomicU64::new(0);
struct Counter;
fn add(n: usize) {
    let live = LIVE.fetch_add(n as u64, Relaxed) + n as u64;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for Counter {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        let p = unsafe { System.alloc(l) }; if !p.is_null() { add(l.size()); } p
    }
    unsafe fn alloc_zeroed(&self, l: Layout) -> *mut u8 {
        let p = unsafe { System.alloc_zeroed(l) }; if !p.is_null() { add(l.size()); } p
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        let q = unsafe { System.realloc(p,l,n) };
        if !q.is_null() {
            if n >= l.size() { add(n-l.size()); }
            else { LIVE.fetch_sub((l.size()-n) as u64, Relaxed); }
        } q
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        unsafe { System.dealloc(p,l) }; LIVE.fetch_sub(l.size() as u64, Relaxed);
    }
}
fn self_test() {
    // Explicit allocation calls keep the optimizer from eliminating the check.
    let start=LIVE.load(Relaxed);
    unsafe {
        let l=Layout::from_size_align(1024,8).unwrap();
        let p=ALLOCATOR.alloc_zeroed(l); assert!(!p.is_null());
        assert_eq!(LIVE.load(Relaxed),start+1024);
        let p=ALLOCATOR.realloc(p,l,4096); assert!(!p.is_null());
        assert_eq!(LIVE.load(Relaxed),start+4096);
        let p=ALLOCATOR.realloc(p,Layout::from_size_align(4096,8).unwrap(),512);
        assert!(!p.is_null()); assert_eq!(LIVE.load(Relaxed),start+512);
        ALLOCATOR.dealloc(p,Layout::from_size_align(512,8).unwrap());
    }
    assert_eq!(LIVE.load(Relaxed),start);
}
#[global_allocator]
static ALLOCATOR: Counter = Counter;
fn main() { self_test();
    let args: Vec<String> = std::env::args().collect();
    assert_eq!(args.len(), 3, "MODE SOURCE");
    assert!(matches!(args[1].as_str(), "vm" | "jit" | "interpreter"));
    let path = std::fs::canonicalize(&args[2]).unwrap();
    let source = std::fs::read_to_string(&path).unwrap();
    let ast = Parser::new(lexer::tokenize(&source).unwrap()).parse();
    if args[1] == "interpreter" {
    let mut interp=kujo::interpreter::Interpreter::new();
    interp.module_loader.add_search_path(path.parent().unwrap());
    let start=LIVE.load(Relaxed); PEAK.store(start,Relaxed);
    interp.eval_stmts(&ast);
    let end=LIVE.load(Relaxed); let peak=PEAK.load(Relaxed);
    assert!(!matches!(interp.return_value,Some(kujo::interpreter::Value::Error(_))));
    eprintln!("LIVE_HEAP start={} end={} peak={} growth={}",start,end,peak,peak.saturating_sub(start));
    return;
}
let chunk = Compiler::new().compile(&ast).unwrap();

    let mut vm = VM::new();
    vm.set_jit_enabled(args[1] == "jit");
    vm.add_module_search_path(path.parent().unwrap());
    let globals = Arc::new(Mutex::new(kujo::interpreter::Environment::new()));
    {
        let mut env = globals.lock().unwrap();
        for (name, value) in kujo::builtins::get_builtins() { env.set(name, value); }
        env.set("null".into(), kujo::interpreter::Value::Null);
    }
    vm.set_globals(globals);
    let start=LIVE.load(Relaxed); PEAK.store(start, Relaxed);
    let result = vm.execute_until_suspend(chunk).and_then(|_| vm.run_scheduler_until_complete_with_timeout(Duration::from_secs(60)));
    let end=LIVE.load(Relaxed); let peak=PEAK.load(Relaxed);
    result.unwrap();
    eprintln!("LIVE_HEAP start={} end={} peak={} growth={}",start,end,peak,peak.saturating_sub(start));
}

